/**
 * Typed contract for the console dataset.
 *
 * `ConsoleIndex` mirrors `public/data/console-index.json`, generated by
 * `scripts/console/build_index.py`. `ConsoleDetail` is composed on the build
 * server from the canonical records, translations and overrides.
 */

export type ConsoleRecordType = "convar" | "command";

export type ConsoleTranslationStatus =
  | "human-edited"
  | "translated"
  | "inferred"
  | "stale"
  | "missing";

export interface ConsoleCategory {
  slug: string;
  zh: string;
  en: string;
}

export interface ConsoleCategorySummary extends ConsoleCategory {
  count: number;
}

export interface ConsoleFlagSummary {
  flag: string;
  count: number;
}

export interface ConsoleIndexRecord {
  key: string;
  name: string;
  type: ConsoleRecordType;
  category: string;
  flags: string[];
  default: string | null;
  summary: string;
  translationStatus: ConsoleTranslationStatus;
  basis: string;
  inferred: boolean;
  /** Never true for inferred, stale, missing, or internal records. */
  indexable: boolean;
}

export interface ConsoleIndexCounts {
  total: number;
  convars: number;
  commands: number;
  withEnglish: number;
  withoutEnglish: number;
  translated: number;
  humanEdited: number;
  inferred: number;
  stale: number;
  missing: number;
  indexable: number;
}

export interface ConsoleIndex {
  schemaVersion: 1;
  upstream: {
    repository: string;
    commit: string;
    fetchedAt: string;
  };
  categories: ConsoleCategory[];
  counts: ConsoleIndexCounts;
  records: ConsoleIndexRecord[];
}

export interface ConsoleRecord {
  type: ConsoleRecordType;
  name: string;
  default?: string;
  min?: string | null;
  max?: string | null;
  flags: string[];
  description: string;
}

export interface ConsoleTranslation {
  zh: string;
  basis: "english" | "name-flags";
  sourceHash: string | null;
  producer: "agent-seed" | "workers-ai";
  model: string;
  promptVersion: string;
  translatedAt: string;
}

export interface ConsoleOverride {
  zh?: string;
  category?: string;
  note?: string;
}

export interface ConsoleUpstream {
  repository: string;
  commit: string;
  fetchedAt: string;
  files: {
    convars: {
      path: string;
      sha256: string;
      bytes: number;
      records: number;
    };
    commands: {
      path: string;
      sha256: string;
      bytes: number;
      records: number;
    };
  };
}

export interface ConsoleMetadata {
  schemaVersion: 1;
  upstream: ConsoleUpstream;
  counts: {
    total: number;
    convars: number;
    commands: number;
    withEnglish: number;
    withoutEnglish: number;
  };
}

export interface ConsoleListLoaderData {
  counts: ConsoleIndexCounts;
  publicCounts: {
    convars: number;
    commands: number;
  };
  categories: ConsoleCategorySummary[];
  flags: ConsoleFlagSummary[];
  upstream: ConsoleIndex["upstream"];
}

export interface ConsoleDetail {
  key: string;
  type: ConsoleRecordType;
  name: string;
  category: string;
  categoryZh: string;
  categoryEn: string;
  flags: string[];
  defaultValue: string | null;
  min: string | null;
  max: string | null;
  /** Original English description from the upstream dump. */
  description: string;
  /** Chinese translation or inferred note; empty when missing. */
  zh: string;
  translationStatus: ConsoleTranslationStatus;
  basis: string;
  inferred: boolean;
  indexable: boolean;
  source: {
    repository: string;
    commit: string;
    fetchedAt: string;
    file: string;
    sha256: string;
  };
  configSnippet: string;
  note?: string;
}
